content.command:
mkdir -p /workspace/repo/feedpin_vendor_sdk && cat > /workspace/repo/feedpin_vendor_sdk/__init__.py << 'EOF'
class PinMismatch(Exception):
    """Raised when a certificate pin does not match."""
    pass

def fingerprint(cert_der: bytes) -> bytes:
    """Return a fingerprint for the given certificate."""
    return cert_der


class PinStore:
    _PINS = {
        "feed.marketdata.example": [b"\x30\x82market-feed-cert"],
    }

    @classmethod
    def load(cls) -> "PinStore":
        return cls()

    def matches(self, host: str, fp: bytes) -> bool:
        return host in self._PINS and fp in self._PINS[host]
EOF

